Here's a C++ program to find the nth number in a sequence where each number is the sum of the three preceding ones, with the first three numbers being 0, -1, -1:

```cpp
#include <iostream>
using namespace std;

// Recursive function to find the nth number in the sequence
// where each number is the sum of the three preceding ones
int sequence(int n) {
    // Base cases for the first three numbers
    if (n == 1) {
        return 0;
    } else if (n == 2) {
        return -1;
    } else if (n == 3) {
        return -1;
    }

    // Recursive case: a(n) = a(n-1) + a(n-2) + a(n-3)
    return sequence(n - 1) + sequence(n - 2) + sequence(n - 3);
}

int main() {
    int n;

    cout << "Enter the position of the number in the sequence (n): ";
    cin >> n;

    // Validate input
    if (n < 1) {
        cout << "Please enter a positive integer." << endl;
        return 1;
    }

    // Calculate and display the nth number in the sequence
    int result = sequence(n);
    cout << "The " << n << "th number in the sequence is: " << result << endl;

    return 0;
}
```

**How it works:**

1. The `sequence(int n)` function uses recursion to calculate the nth number in the sequence.
2. **Base cases:**
   - If n = 1, return 0 (first number)
   - If n = 2, return -1 (second number)
   - If n = 3, return -1 (third number)
3.

